async function main(ctx) {
  const input = ctx.input || {};

  const cardId = input.cardId != null ? String(input.cardId).trim() : '';
  const toColumnName = input.toColumnName != null ? String(input.toColumnName).trim() : '';

  if (!cardId) throw new Error('cardId is required');
  if (!toColumnName) throw new Error('toColumnName is required');

  const args = { cardId, toColumnName };

  if (input.toPos !== undefined) {
    const n = Number(input.toPos);
    if (!Number.isFinite(n)) throw new Error('toPos must be a number');
    args.toPos = n;
  }

  if (input.toColumnId !== undefined) {
    const s = input.toColumnId === null ? '' : String(input.toColumnId).trim();
    if (s) args.toColumnId = s;
  }

  return args;
}

